"""وحدات القيم الجديدة. كل وحدة: كلمات، جمل، حديث، قصة قصيرة، وتحدٍّ في الحياة اليومية.
ترتيب اللغات في L و W و S: ar, en, fr, es, de, it
"""

L = lambda ar, en, fr, es, de, it: {"ar": ar, "en": en, "fr": fr, "es": es, "de": de, "it": it}


def W(ar, tr, emoji, ar_m, en, fr, es, de, it):
    return {"ar": ar, "tr": tr, "emoji": emoji, "m": L(ar_m, en, fr, es, de, it)}


def S(who, ar, tr, en, fr, es, de, it):
    return {"who": who, "ar": ar, "tr": tr, "m": {"en": en, "fr": fr, "es": es, "de": de, "it": it}}


def H(ar, src_ar, src_latin, m, lesson):
    return {"ar": ar, "src": {"ar": src_ar, "latin": src_latin}, "m": m, "lesson": lesson}


